+public abstract class AbstractNioBossPool<E extends Boss>
+        implements BossPool<E>, ExternalResourceReleasable {
+
+    private final Boss[] bosses;
+    private final AtomicInteger bossIndex = new AtomicInteger();
+    private final Executor bossExecutor;
+    private volatile  boolean initDone;
+
+    /**
+     * Create a new instance
+     *
+     * @param bossExecutor the {@link Executor} to use for the {@link org.jboss.netty.channel.socket.nio.Boss}'s
+     * @param bossCount the count of {@link org.jboss.netty.channel.socket.nio.Boss}'s to create
+     */
+    AbstractNioBossPool(Executor bossExecutor, int bossCount) {
+        this(bossExecutor, bossCount, true);
+    }
+
+    AbstractNioBossPool(Executor bossExecutor, int bossCount, boolean autoInit) {
+        if (bossExecutor == null) {
+            throw new NullPointerException("bossExecutor");
+        }
+        if (bossCount <= 0) {
+            throw new IllegalArgumentException(
+                    "bossCount (" + bossCount + ") " +
+                            "must be a positive integer.");
+        }
+        bosses = new Boss[bossCount];
+        this.bossExecutor = bossExecutor;
+        if (autoInit) {
+            init();
+        }
+    }
+
+    protected void init() {
+        if (initDone) {
+            throw new IllegalStateException("Init was done before");
+        }
+        initDone = true;
+
+        for (int i = 0; i < bosses.length; i++) {
+            bosses[i] = createBoss(bossExecutor);
+        }
+    }
+
+    /**
+     * Create a new {@link org.jboss.netty.channel.socket.nio.Boss} which uses the given {@link Executor} to service IO
